#!/usr/bin/env python3
import subprocess, os, shutil, json
EXE = "/workspace/executable"

def run_site(body, files=None, config=None, name="wl"):
    d = f"/tmp/probe-md/{name}"
    shutil.rmtree(d, ignore_errors=True)
    os.makedirs(d + "/input/content")
    open(d + "/input/content/post.md", "w").write("---\ntitle: Probe Post\ndate: 2026-01-15\n---\n" + body)
    if config is not None:
        open(d + "/input/marmite.yaml", "w").write(config)
    if files:
        for p, c in files.items():
            fp = os.path.join(d, "input", p)
            os.makedirs(os.path.dirname(fp), exist_ok=True)
            open(fp, "w").write(c)
    subprocess.run([EXE, d + "/input", d + "/output"], capture_output=True)
    return d + "/output"

def content_html(outdir):
    data = open(outdir + "/probe-post.html").read()
    m = '<div class="content-html e-content">'
    i = data.index(m) + len(m)
    endmark = '\n  \n  <footer class="data-tags-footer">'
    k = data.index(endmark, i)
    return data[i:k-len('</div>')]

# wikilink charset sweep: one wikilink per line, display text 'xCy'
chars = list("!\"$'()*+,-.;<=>@[\\]^`{|} \t") + ['%', '&', '/', ':', '?', '#', '_', '.', '~']
for c in chars:
    body = f"[[x{c}y]]"
    try:
        out = content_html(run_site(body, name="wlc"))
    except Exception as e:
        out = f"ERROR {e}"
    print(f"char {c!r}: {out.strip()!r}")
for special in ["[[x.html]]", "[[x y/z]]", "[[ x ]]", "[[x ]]", "[[ x]]", "[[x#y]]", "[[x#y z]]", "[[x?y z]]", "[[http://e.com/x]]", "[[a|b|c]]", "[[]]", "[[x|]]", "[[|x]]"]:
    try:
        out = content_html(run_site(special, name="wls"))
    except Exception as e:
        out = f"ERROR {e}"
    print(f"special {special!r}: {out.strip()!r}")

